#!/usr/bin/env node
/*
 * Add crawler-facing metadata to the published demo build.
 *
 * `site/demo.html` is generated by the ArchRay CLI from examples/freshmart.graph.json.
 * The same generator also produces user-owned local maps, so these tags must not
 * be baked into the generator or viewer/index.html. This script touches only the
 * site copy and is chained after the site build in package.json.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const FILE = path.join(ROOT, 'site', 'demo.html');
const CANONICAL = 'https://archray.dev/demo';
const DESCRIPTION = 'Explore a live ArchRay demo: an interactive 3D and 2D architecture map of the FreshMart sample app, built from real source with file-and-line evidence.';
const H1 = 'ArchRay Live Demo — Interactive 3D and 2D Architecture Map';
const HEAD_START = '<!-- archray:seo:head:start -->';
const HEAD_END = '<!-- archray:seo:head:end -->';
const BODY_START = '<!-- archray:seo:body:start -->';
const BODY_END = '<!-- archray:seo:body:end -->';
const ROOT_MARKUP = '<div id="root"></div>';

if (DESCRIPTION.length < 70 || DESCRIPTION.length > 160) {
  throw new Error(`demo description must be 70-160 characters, got ${DESCRIPTION.length}`);
}

function removeBlock(html, start, end) {
  let output = html;
  for (;;) {
    const from = output.indexOf(start);
    if (from === -1) return output;
    const to = output.indexOf(end, from + start.length);
    if (to === -1) throw new Error(`unterminated block: ${start}`);
    const lineStart = output.lastIndexOf('\n', from) + 1;
    const lineEnd = output.indexOf('\n', to + end.length);
    output = output.slice(0, lineStart) + output.slice(lineEnd + 1);
  }
}

function count(html, pattern) {
  return (html.match(pattern) ?? []).length;
}

function attrs(html, pattern) {
  return html.match(pattern)?.[1] ?? null;
}

const original = readFileSync(FILE, 'utf8');
const title = attrs(original, /<title>([\s\S]*?)<\/title>/i);
const lang = attrs(original, /<html\b[^>]*\blang="([^"]*)"/i);
const rootMatch = original.match(/^([ \t]*)<div id="root"><\/div>/m);
const bodyIndent = rootMatch?.[1] ?? '  ';
const viewportMatch = original.match(/^[ \t]*<meta name="viewport"[^>]*>/m);
if (!title) throw new Error('demo title not found');
if (!lang) throw new Error('demo lang not found');
if (!rootMatch) throw new Error('demo root mount not found');
if (!viewportMatch) throw new Error('demo viewport not found');
if (!original.includes('</head>')) throw new Error('demo head close not found');

let html = removeBlock(original, HEAD_START, HEAD_END);
html = removeBlock(html, BODY_START, BODY_END);

const headBlock = [
  HEAD_START,
  `  <meta name="description" content="${DESCRIPTION}">`,
  `  <link rel="canonical" href="${CANONICAL}">`,
  HEAD_END
].join('\n');
const bodyBlock = [
  BODY_START,
  `${bodyIndent}  <h1 style="position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap;border:0;">${H1}</h1>`,
  `${bodyIndent}${BODY_END}`
].join('\n');

html = html.replace(viewportMatch[0], `${viewportMatch[0]}\n${headBlock}`);
html = html.replace(ROOT_MARKUP, `${bodyBlock}\n${bodyIndent}${ROOT_MARKUP}`);

const afterTitle = attrs(html, /<title>([\s\S]*?)<\/title>/i);
const afterLang = attrs(html, /<html\b[^>]*\blang="([^"]*)"/i);
if (afterTitle !== title) throw new Error('demo title changed unexpectedly');
if (afterLang !== lang) throw new Error('demo lang changed unexpectedly');
if (count(html, /<h1\b/gi) !== 1) throw new Error(`expected exactly one h1, got ${count(html, /<h1\b/gi)}`);
if (count(html, /<link\b[^>]*rel="canonical"[^>]*>/gi) !== 1) throw new Error('expected exactly one canonical');
if (count(html, /<meta\b[^>]*name="description"[^>]*>/gi) !== 1) throw new Error('expected exactly one description');

writeFileSync(FILE, html);
console.log(`seo-postprocess-demo: ${path.relative(ROOT, FILE)} (${DESCRIPTION.length}-char description, canonical ${CANONICAL})`);
